intros ht_int_pos ht_int_neg
have h_exp_pos_int : MeasureTheory.Integrable (fun ω => Real.exp (t * X ω)) μ := ht_int_pos
have h_exp_neg_int : MeasureTheory.Integrable (fun ω => Real.exp (-t * X ω)) μ := ht_int_neg
let f := fun ω => Real.exp (|t| * |X ω|)
have h_f_nonneg : ∀ᵐ ω ∂μ, 0 ≤ f ω := by intros ω; exact le_rfl
have h_f_int : MeasureTheory.Integrable f μ :=
  by {
    let g := fun ω => Real.exp (t * X ω)
    let h := fun ω => Real.exp (-t * X ω)
    have h_g_int : MeasureTheory.Integrable g μ := h_exp_pos_int
    have h_h_int : MeasureTheory.Integrable h μ := h_exp_neg_int
    let g_abs := fun ω => Real.exp (|t| * |X ω|)
    let h_abs := fun ω => Real.exp (|t| * |X ω|)
    have h_g_abs : ∀ᵐ ω ∂μ, g ω ≤ g_abs ω := by intros ω; exact exp_le_exp (le_abs t) (le_abs (X ω))
    have h_h_abs : ∀ᵐ ω ∂μ, h ω ≤ h_abs ω := by intros ω; exact exp_le_exp (le_abs (-t)) (le_abs (X ω))
    have h_g_abs_int : MeasureTheory.Integrable g_abs μ :=
      by {
        apply MeasureTheory.Integrable.mono'
        exact h_g_int
        exact h_g_abs
      }
    have h_h_abs_int : MeasureTheory.Integrable h_abs μ :=
      by {
        apply MeasureTheory.Integrable.mono'
        exact h_h_int
        exact h_h_abs
      }
    have h_g_abs_eq_h_abs : ∀ᵐ ω ∂μ, g_abs ω = h_abs ω := by intros ω; exact eq_rfl
    have h_g_abs_int_eq_h_abs_int : MeasureTheory.Integrable g_abs μ ∧ MeasureTheory.Integrable h_abs μ :=
      And.intro h_g_abs_int h_h_abs_int
    have h_f_int' : MeasureTheory.Integrable f μ :=
      by {
        apply MeasureTheory.Integrable.cong_ae
        exact h_g_abs_eq_h_abs
        exact h_g_abs_int_eq_h_abs_int
      }
  }
exact h_f_int
